#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXV 8
static int visited[MAXV];
static int queue_[MAXV];
static int adj[MAXV][MAXV];

int main(int argc, char **argv) {
    if ((argc - 1) & 1) { puts("INVALID_INPUT"); return 1; }
    memset(adj, 0, sizeof(adj));
    for (int i = 1; i + 1 < argc; i += 2) {
        char *endptr;
        long u = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0' || u < 0 || u >= MAXV) { puts("INVALID_INPUT"); return 1; }
        long v = strtol(argv[i+1], &endptr, 10);
        if (*endptr != '\0' || v < 0 || v >= MAXV) { puts("INVALID_INPUT"); return 1; }
        adj[u][v] = 1; adj[v][u] = 1;
    }
    memset(visited, 0, sizeof(visited));
    int comp_index = 0;
    for (int start = 0; start < MAXV; ++start) {
        if (visited[start]) continue;
        int qhead = 0, qtail = 0;
        queue_[qtail++] = start; visited[start] = 1;
        int component[MAXV]; int comp_sz = 0; component[comp_sz++] = start;
        while (qhead < qtail) {
            int cur = queue_[qhead++];
            for (int nxt = 0; nxt < MAXV; ++nxt) {
                if (adj[cur][nxt] && !visited[nxt]) {
                    visited[nxt] = 1; queue_[qtail++] = nxt; component[comp_sz++] = nxt;
                }
            }
        }
        printf("%d:", comp_index++);
        printf(" {");
        for (int i = 0; i < comp_sz; ++i) {
            if (i) putchar(',');
            printf("%d", component[i]);
        }
        putchar('}'); putchar('\n');
    }
    return 0;
}
